(function(){const t=document.createElement("script");t.src=chrome.runtime.getURL("src/content/interceptor.ts");t.onload=()=>t.remove();(document.head||document.documentElement).appendChild(t);window.addEventListener("message",e=>{e.source===window&&(e.data.type!=="ASTOCK_XHR_DATA"&&e.data.type!=="ASTOCK_FETCH_DATA"||chrome.runtime.sendMessage({type:"CAPTURED_DATA",url:e.data.url,body:e.data.response,status:e.data.status}))});function n(){const e=window.location.pathname.match(/\/(\d{6})\/?/);e&&chrome.runtime.sendMessage({type:"PAGE_STOCK_CODE",code:e[1],url:window.location.href})}n();let o=window.location.href;const r=new MutationObserver(()=>{window.location.href!==o&&(o=window.location.href,n())});r.observe(document.body||document.documentElement,{childList:!0,subtree:!0});
})()
